4	
5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ResponseEntity;
7	import org.springframework.http.converter.HttpMessageNotReadableException;
8	import org.springframework.web.bind.MethodArgumentNotValidException;
9	import org.springframework.web.bind.annotation.ExceptionHandler;
10	import org.springframework.web.bind.annotation.RestControllerAdvice;
11	
12	/**
13	 * 统一错误响应：{"code": "...", "message": "..."}。
14	 */
15	@RestControllerAdvice
16	public class ApiExceptionHandler {
17	
18	    public record ErrorBody(String code, String message) {
19	    }
20	
21	    @ExceptionHandler(ApiException.class)
22	    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
23	        return ResponseEntity.status(ex.status())
24	                .body(new ErrorBody(ex.code(), ex.getMessage()));
25	    }
26	
27	    @ExceptionHandler(MethodArgumentNotValidException.class)
28	    public ResponseEntity<ErrorBody> handleValidation(MethodArgumentNotValidException ex) {
29	        String message = ex.getBindingResult().getFieldErrors().stream()
30	                .map(error -> error.getField() + " " + error.getDefaultMessage())
31	                .collect(Collectors.joining("; "));
32	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
33	                .body(new ErrorBody("VALIDATION_FAILED", message));
34	    }
35	
